import type { DownloadRequest } from './bindings/DownloadRequest';
import type { ErrorPayload } from './bindings/ErrorPayload';

export function isErrorPayload(e: unknown): e is ErrorPayload {
  return typeof e === 'object' && e !== null && 'code' in e && 'message' in e;
}

/** Normalise anything thrown into an ErrorPayload. */
export function toError(e: unknown): ErrorPayload {
  if (isErrorPayload(e)) return e;
  if (typeof e === 'object' && e !== null && 'error' in e && isErrorPayload((e as { error: unknown }).error)) {
    return (e as { error: ErrorPayload }).error;
  }
  const message = e instanceof Error ? e.message : typeof e === 'string' ? e : 'Something went wrong.';
  return { code: 'unknown', message, hint: null, detail: e instanceof Error ? e.stack ?? null : null };
}

export function emptyRequest(url: string): DownloadRequest {
  return {
    url,
    mode: 'video',
    title: null,
    thumbnail: null,
    platform: null,
    duration: null,
    summary: null,
    tier: null,
    container: 'mp4',
    videoId: null,
    audioId: null,
    combined: false,
    silent: false,
    pickVcodec: null,
    pickExt: null,
    expectedVideo: null,
    expectedAudio: null,
    audioFormat: 'mp3',
    audioQuality: 'best',
    audioSourceId: null,
    playlist: false,
    playlistCount: null,
    playlistLimit: null,
    referer: null,
    cut: null,
  };
}
